CREATE TABLE IF NOT EXISTS locations (id SERIAL PRIMARY KEY, name TEXT NOT NULL, latitude DOUBLE PRECISION NOT NULL, longitude DOUBLE PRECISION NOT NULL, timezone TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS chat_history (id BIGSERIAL PRIMARY KEY, question TEXT NOT NULL, answer TEXT NOT NULL, location_id INTEGER REFERENCES locations(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS alert_subscriptions (id BIGSERIAL PRIMARY KEY, location_id INTEGER REFERENCES locations(id), channel TEXT NOT NULL, destination TEXT, threshold TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS weather_snapshots (id BIGSERIAL PRIMARY KEY, location_id INTEGER REFERENCES locations(id), payload JSONB NOT NULL, source TEXT NOT NULL, observed_at TIMESTAMPTZ NOT NULL, fetched_at TIMESTAMPTZ NOT NULL DEFAULT now());
